const data = $input.first().json;
let chatId = '';
let text = '';
let callbackData = '';
let isCallback = false;
let messageId = null;
let callbackQueryId = null;
let originalMsgText = '';

if (data.message) {
  chatId = String(data.message.chat.id);
  text = data.message.text || '';
} else if (data.callback_query) {
  isCallback = true;
  chatId = String(data.callback_query.message.chat.id);
  messageId = data.callback_query.message.message_id;
  callbackData = data.callback_query.data;
  callbackQueryId = data.callback_query.id;
  originalMsgText = data.callback_query.message.text || '';
}

return { json: { chatId, text, callbackData, isCallback, messageId, callbackQueryId, originalMsgText } };

const inputData = $('Parse Input').first().json;
const users = $input.all();
const chatId = String(inputData.chatId);

let user = users.find(u => String(u.json['Telegram ID']) === chatId);
let state = user ? (user.json.State || 'new') : 'new';
let action = 'ignore';
let rooms = user ? (user.json.Rooms || '') : '';

if (inputData.text === '/start') {
  action = 'ask_rooms';
} else if (inputData.text === '/stop') {
  action = 'stop_bot';
} else if (state === 'waiting_rooms' && inputData.isCallback) {
  action = 'ask_district';
  rooms = inputData.callbackData.replace('rooms_', '').replace('plus', '+');
} else if (state === 'waiting_district' && inputData.isCallback) {
  if (inputData.callbackData === 'confirm_districts' || inputData.callbackData === 'district_any') {
    action = 'ask_min_area';
  } else if (inputData.callbackData.startsWith('district_')) {
    action = 'toggle_district';
  }
} else if (state === 'waiting_min_area' && !inputData.isCallback) {
  if (!isNaN(inputData.text) && parseInt(inputData.text) >= 10 && parseInt(inputData.text) <= 500) {
    action = 'ask_max_area';
  } else {
    action = 'invalid_area';
  }
} else if (state === 'waiting_max_area' && !inputData.isCallback) {
  if (!isNaN(inputData.text) && parseInt(inputData.text) >= 10 && parseInt(inputData.text) <= 500) {
    action = 'ask_price';
  } else {
    action = 'invalid_area';
  }
} else if (state === 'waiting_price' && !inputData.isCallback) {
  if (!isNaN(inputData.text) && parseInt(inputData.text) >= 4000 && parseInt(inputData.text) <= 20000) {
    action = 'ask_vetting';
  } else {
    action = 'invalid_price';
  }
} else if (state === 'waiting_vetting' && !inputData.isCallback) {
  action = 'finish';
// НОВІ УМОВИ ДЛЯ КНОПОК:
} else if (inputData.isCallback && inputData.callbackData.startsWith('view_')) {
  action = 'notify_view';
} else if (inputData.isCallback && inputData.callbackData.startsWith('ask_')) {
  action = 'notify_ask';
} else if (inputData.isCallback && inputData.callbackData.startsWith('hide_')) {
  action = 'hide_message';
}

return { 
  json: { 
    chatId: inputData.chatId, 
    state, 
    action, 
    text: inputData.text, 
    callbackData: inputData.callbackData, 
    callbackQueryId: inputData.callbackQueryId, 
    messageId: inputData.messageId, 
    rooms, 
    originalMsgText: inputData.originalMsgText, 
    adminTopicId: user ? user.json['Admin Topic ID'] : "1958" 
  } 
};

const update = $input.first().json;
const adminGroup = -1004341021033;

if (!update.message) return [];

// 1. Адмін пише відповідь клієнту
if (update.message.chat.id == adminGroup && update.message.message_thread_id) {
  if (update.message.text) {
    return [{ json: { action: 'admin_reply', text: update.message.text, message_thread_id: update.message.message_thread_id } }];
  }
  return []; 
}

// 2. Клієнт пише боту
if (update.message.chat.id > 0 && update.message.text !== '/start') {
  // Захист: якщо клієнт прислав тільки цифри (вводить бюджет) — не пересилаємо це в CRM
  if (/^\s*\d+\s*$/.test(update.message.text)) {
      return []; 
  }

  let replyText = "";
  if (update.message.reply_to_message) {
      replyText = update.message.reply_to_message.text || update.message.reply_to_message.caption || "";
  }
  return [{ json: { action: 'user_message', telegram_id: update.message.chat.id, message_id: update.message.message_id, reply_text: replyText } }];
}

return [];

