const input = $input.first().json;
const users = $('Read User State').all();
let user = users.find(u => String(u.json['Telegram ID']) === String(input.chatId));
let currentStr = user ? (user.json.District || '') : '';

let selected = currentStr ? currentStr.split(',').map(s => s.trim()).filter(s => s) : [];

if (input.action === 'toggle_district') {
  const clicked = input.callbackData.replace('district_', '');
  if (selected.includes(clicked)) {
    selected = selected.filter(s => s !== clicked);
  } else {
    selected.push(clicked);
  }
} else if (input.action === 'ask_district') {
  selected = []; 
}

const districts = [
  "Bemowo", "Białołęka", "Bielany", "Mokotów", "Ochota", 
  "Praga-Południe", "Praga-Północ", "Rembertów", "Śródmieście", 
  "Targówek", "Ursus", "Ursynów", "Wawer", "Wesoła", 
  "Wilanów", "Włochy", "Wola", "Żoliborz"
];

const buttons = [];
let row = [];
for (let i = 0; i < districts.length; i++) {
  const d = districts[i];
  const isSelected = selected.includes(d.toLowerCase());
  const text = (isSelected ? "✅ " : "") + d;
  row.push({
    text: text,
    callback_data: "district_" + d.toLowerCase()
  });

  if (row.length === 2 || i === districts.length - 1) {
    buttons.push(row);
    row = [];
  }
}

buttons.push([{ text: "Будь-який район (вся Варшава)", callback_data: "district_any" }]);
if (selected.length > 0) {
  buttons.push([{ text: "✅ Підтвердити (" + selected.length + ")", callback_data: "confirm_districts" }]);
}

const newDistrictStr = selected.join(', ');

return {
  json: {
    chatId: input.chatId,
    messageId: input.messageId,
    action: input.action,
    newDistrictStr: newDistrictStr,
    rooms: input.rooms || '',
    replyMarkup: {
      inline_keyboard: buttons
    }
  }
};
